xql_query:
// ============================================================
// Rule: WIN_Disable UAC Registry Change
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Disable UAC Registry Change.
// Severity: SEV_040_HIGH
// Category: TAMPERING
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1562.001 - Impair Defenses: Disable or Modify Tools

// Configuração inicial: define que as comparações de strings não diferenciam maiúsculas/minúsculas
config case_sensitive = false  

// Fonte de dados: eventos coletados pelo Cortex XDR
| dataset = xdr_data  

// Filtro para selecionar apenas eventos de modificação de chave de registro
// - event_type = REGISTRY → evento de registro do Windows
// - event_sub_type = REGISTRY_SET_VALUE → operação de alteração de valor no registro
| filter event_type = ENUM.REGISTRY and event_sub_type = ENUM.REGISTRY_SET_VALUE  

// Seleção dos campos relevantes para análise de alteração de registro
| fields _time,                         // Data e hora do evento
         agent_hostname,                // Host onde ocorreu a alteração
         actor_process_image_name,      // Processo que realizou a modificação
         action_registry_key_name,      // Caminho da chave de registro alterada
         action_registry_value_name,    // Nome do valor dentro da chave
         action_registry_data           // Novo dado definido no valor

// Filtro adicional: identifica modificações na chave de registro
// HKLM\Software\Microsoft\Windows\CurrentVersion\Policies\System
// - Valor "EnableLUA" → controla o UAC (User Account Control)
// - Definido como "0" → desabilita o UAC, o que reduz a proteção do sistema
| filter lowercase(action_registry_key_name) = "hklm\\software\\microsoft\\windows\\currentversion\\policies\\system"
        and lowercase(action_registry_value_name) = "enablelua"
        and action_registry_data = "0"
